import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const f=JSON.parse('{"title":"Checkers","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/checkers.md","filePath":"architecture/checkers.md"}'),c={name:"architecture/checkers.md"};function o(d,e,n,i,l,h){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="checkers" tabindex="-1">Checkers <a class="header-anchor" href="#checkers" aria-label="Permalink to &quot;Checkers&quot;">​</a></h1><p>Checkers are queries over the program graph. The current set:</p><table tabindex="0"><thead><tr><th>Checker</th><th>What it reports</th></tr></thead><tbody><tr><td>Taint reachability</td><td>Source-to-sink flows for XSS, SQLi, command injection, SSRF, path traversal, IDOR.</td></tr><tr><td>Session-trust / guard bypass</td><td>Authentication guards that a flow escapes.</td></tr><tr><td>Use-after-free / double-free</td><td>Dangling use or repeated deallocation, including through wrapper functions (interprocedural allocation summaries).</td></tr><tr><td>Out-of-bounds</td><td>Indexed accesses that escape every bounding guard, judged against the value lattice.</td></tr><tr><td>Policy</td><td>Program-level rules: required calls (e.g. an authorization helper) and forbidden calls, at function or module scope.</td></tr><tr><td>Learned checks</td><td>Facts learned from the corpus: sources, sinks, sanitisers, policies, merged from <code>.frc</code> bundles.</td></tr></tbody></table><h2 id="learned-facts" tabindex="-1">Learned facts <a class="header-anchor" href="#learned-facts" aria-label="Permalink to &quot;Learned facts&quot;">​</a></h2><p>Bundles can contribute five kinds of facts: <strong>Source</strong>, <strong>Sink</strong>, <strong>Sanitizer</strong>, <strong>Policy</strong>, and <strong>Check</strong>. Learned <code>unless_range_check</code> requirements are satisfied by guards the value lattice proves, not by the mere textual presence of a call.</p>',5)])])}const p=t(c,[["render",o]]);e